// =====================================================================
// n8n - Code node (Mode : "Run Once for All Items")  — "Construction Prompt"
// Objectif : construire le prompt LLM qui associe chaque ligne d'une
//            facture fournisseur (SRM) à un code article Sage X3 (ITMREF_0).
//
// Entrée facture : 1 item n8n par ligne, au format
//   { designation, quantite, prix_unitaire, quantite_num, prix_unitaire_num, fichier }
// Entrée catalogue : [ { data: [ {ITMREF_0, ITMDES1_0}, ... ] } ]
// Sortie : { systemPrompt, userPrompt, messages, requestBody, ... }
//          -> à brancher sur le node HTTP Request (Mistral / Groq)
// =====================================================================

// ---------------------------------------------------------------------
// 1) ENTRÉES  (adapter les noms de nodes à votre workflow)
// ---------------------------------------------------------------------
const articlesInternes = $('Aggregate').all()
  .flatMap(i => Array.isArray(i.json.data) ? i.json.data : [i.json]);
const brut = $('Code2').all().map(i => i.json);

const FOURNISSEUR_CODE = 'T6516'; // code Sage X3 du fournisseur (SRM)
const FOURNISSEUR_NOM  = 'SRM Casablanca-Settat';

// Convertit "381 660" / "0,90383" / 12 / null en nombre (ou null)
const parseNombre = v => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const n = Number(String(v).replace(/[\s\u00a0\u202f]/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};

const lignesFacture = brut
  .filter(l => l && l.designation)
  .map((l, idx) => ({
    ligne: idx + 1,
    designation: String(l.designation).replace(/\s+/g, ' ').trim(),
    // on privilégie les champs numériques déjà convertis, sinon on parse le texte
    quantite: parseNombre(l.quantite_num ?? l.quantite),
    prix_unitaire: parseNombre(l.prix_unitaire_num ?? l.prix_unitaire),
  }));

if (!lignesFacture.length) throw new Error('Aucune ligne de facture reçue');

const fournisseur = {
  code: FOURNISSEUR_CODE,
  nom: FOURNISSEUR_NOM,
  fichier: brut[0].fichier || null,
  nb_lignes: lignesFacture.length,
};

// ---------------------------------------------------------------------
// 2) CATALOGUE INTERNE (dédoublonné, nettoyé)
// ---------------------------------------------------------------------
const mapArticles = new Map();
for (const a of articlesInternes) {
  const code = String(a.ITMREF_0 || '').trim();
  if (!code) continue;
  const designation = String(a.ITMDES1_0 || '').replace(/\s+/g, ' ').trim();
  const prix = a.PRI_0 !== undefined && a.PRI_0 !== null ? Number(a.PRI_0) : null;
  if (!mapArticles.has(code)) {
    mapArticles.set(code, { code_article: code, designation_interne: designation, prix_reference: prix });
  } else if (prix !== null) {
    const ex = mapArticles.get(code);
    ex.prix_reference = ex.prix_reference === null ? prix : Math.max(ex.prix_reference, prix);
  }
}
const catalogue = Array.from(mapArticles.values());

if (!catalogue.length) throw new Error('Catalogue interne vide : vérifier le node SQL');

// ---------------------------------------------------------------------
// 3) BLOCS DE TEXTE
// ---------------------------------------------------------------------
const SEP = '═══════════════════════════════════════════';

const blocCatalogue = catalogue.map((a, i) =>
  `${i + 1}. code_article: ${a.code_article}
   designation_interne: ${a.designation_interne}` +
  (a.prix_reference !== null ? `\n   prix_reference: ${a.prix_reference}` : '')
).join('\n\n');

const blocFacture = lignesFacture.map(l =>
  `${l.ligne}. designation: ${l.designation}
   quantite: ${l.quantite ?? 'non précisée'}
   prix_unitaire: ${l.prix_unitaire ?? 'non précisé'}`
).join('\n\n');

// ---------------------------------------------------------------------
// 4) PROMPT
// ---------------------------------------------------------------------
const systemPrompt = `Tu es un assistant de rapprochement de factures fournisseurs pour un ERP Sage X3 (entreprise industrielle marocaine).
Ta mission : pour chaque ligne de la facture, retrouver l'article interne correspondant et retourner son code_article avec le prix unitaire et la quantité facturés.`;

const userPrompt = `${SEP}
CONTEXTE
${SEP}
Fournisseur : ${fournisseur.nom}
code_fournisseur : ${fournisseur.code}
Nombre de lignes facture : ${lignesFacture.length}

${SEP}
ARTICLES INTERNES (source système — articles référencés pour ce fournisseur)
${SEP}
${blocCatalogue}

${SEP}
LIGNES DE LA FACTURE REÇUE
${SEP}
${blocFacture}

${SEP}
ALGORITHME DE MATCHING
${SEP}

Pour chaque ligne de la facture, dans cet ordre :

ÉTAPE 1 — Correspondance exacte
→ Même désignation après normalisation (majuscules, sans accents, sans ponctuation, espaces multiples et finaux ignorés)
→ Ex : "ENERGIE ACTIVE H. PLEINES" = "ENERGIE ACTIVE H. PLEINES  "

ÉTAPE 2 — Correspondance sémantique
→ Même article avec fautes de frappe, abréviations ou troncatures dans le catalogue
→ Ex : "ENTRETIEN BRANCHEMENT" = "ENTRETION BRANCHEMET", "PUISSANCE" = "PUIS", "SOUSCRITE" = "SOUSC"

ÉTAPE 3 — Aucune correspondance
→ Aucun article interne ne ressemble à cette ligne
→ code_article = null, designation_interne = null

${SEP}
RÈGLES STRICTES
${SEP}

DISTINCTION DES VARIANTES (ne jamais confondre) :
- H. PLEINES / H. CREUSES / H. DE POINTE
- ENTRETIEN COMPTAGE / LOCATION COMPTAGE / ENTRETIEN BRANCHEMENT
- REDEVANCE DE PUISSANCE / DEPASSEMENT DE LA PUIS SOUSC

ARTICLES GÉNÉRIQUES :
- "CONSOMMATION ELECTRICITE" et "CONSOMMATION D'EAU" : à utiliser uniquement si aucune désignation plus précise ne correspond
- "FRAIS DE TIMBRE SUR REGLEMENT ESPECE" : uniquement si la ligne facture parle explicitement de timbre

PRIX UNITAIRE ET QUANTITÉ :
- Recopier quantite et prix_unitaire de la ligne facture tels quels, sans les recalculer ni les arrondir
- Ce sont déjà des nombres : les restituer en nombres (pas de texte, pas d'espace, point comme séparateur décimal)
- Les frais forfaitaires ont quantite = 1 : les recopier normalement
- Valeur réellement absente → null
- prix_reference (catalogue, s'il existe) sert seulement à confirmer un doute entre deux articles, jamais à remplacer le prix de la facture

CODES ARTICLES :
- Utiliser UNIQUEMENT les codes de la liste des articles internes
- Ne jamais inventer un code_article
- Un code_article ne peut être attribué qu'à une seule ligne de la facture
- En cas de doute entre deux articles, choisir null plutôt qu'un mauvais code

${SEP}
SORTIE ATTENDUE
${SEP}
Retourne UNIQUEMENT ce JSON valide, sans texte avant ni après, sans backticks :

{
  "lignes": [
    {
      "ligne": 1,
      "designation_fournisseur": "",
      "designation_interne": "",
      "code_article": "",
      "prix_unitaire": 0,
      "quantite": 0
    }
  ]
}

RAPPEL FINAL :
- Une entrée par ligne de la facture, dans le même ordre (${lignesFacture.length} entrées)
- ligne = numéro de la ligne facture (1 à ${lignesFacture.length})
- designation_fournisseur = désignation exacte de la facture
- designation_interne = désignation du catalogue interne correspondant
- Aucun code_article inventé
- JSON pur uniquement, sans markdown ni explication`;

// ---------------------------------------------------------------------
// 5) SORTIE
// ---------------------------------------------------------------------
const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: userPrompt },
];

return [{
  json: {
    fournisseur,
    nb_articles_catalogue: catalogue.length,
    nb_lignes_facture: lignesFacture.length,
    catalogue,        // utilisé par le node de parsing
    lignesFacture,    // utilisé par le node de parsing
    systemPrompt,
    userPrompt,
    messages,
    requestBody: {
      model: 'codestral-latest', // ou 'mistral-large-latest' / modèle Groq
      temperature: 0,
      response_format: { type: 'json_object' },
      messages,
    },
  },
}];

// =====================================================================
// n8n - Code node (Mode : "Run Once for All Items")
// À placer juste après l'appel Mistral.
// Retourne uniquement le contenu généré par le LLM : 1 item par ligne
//   { designation_fournisseur, designation_interne, code_article, prix_unitaire, quantite }
// Autonome : ne dépend d'aucun autre node.
// =====================================================================

const reponse = $input.first().json;

// 1) Texte généré par le LLM
let contenu =
  reponse.choices?.[0]?.message?.content ??
  reponse.output ??
  reponse.text ??
  '';

if (Array.isArray(contenu)) {
  contenu = contenu.map(c => (typeof c === 'string' ? c : c.text || '')).join('');
}
contenu = typeof contenu === 'object' ? JSON.stringify(contenu) : String(contenu);

// 2) Retirer ```json ... ``` et isoler le JSON
let t = contenu.replace(/```(?:json)?/gi, '').trim();
const debut = t.search(/[{\[]/);
const fin = Math.max(t.lastIndexOf('}'), t.lastIndexOf(']'));
if (debut === -1 || fin === -1) {
  throw new Error('Aucun JSON dans la réponse du LLM : ' + contenu.slice(0, 200));
}
t = t.slice(debut, fin + 1);

let parsed;
try {
  parsed = JSON.parse(t);
} catch (e) {
  parsed = JSON.parse(t.replace(/,\s*([}\]])/g, '$1')); // virgules finales
}

// 3) Lignes
const lignes = Array.isArray(parsed) ? parsed : (parsed.lignes || []);
if (!lignes.length) throw new Error('Le LLM n\'a retourné aucune ligne');

// 4) Sortie : 1 item par ligne, 5 champs
return lignes.map(l => ({
  json: {
    designation_fournisseur: l.designation_fournisseur ?? null,
    designation_interne: l.designation_interne ?? null,
    code_article: l.code_article ?? null,
    prix_unitaire: l.prix_unitaire ?? null,
    quantite: l.quantite ?? null,
  },
}));

const sortie = $input.first().json;

// Vérifier l'exécution
if (sortie.exitCode !== 0) {
  throw new Error(`Script Python en erreur (exitCode ${sortie.exitCode}) : ${sortie.stderr || sortie.stdout}`);
}

// Parser le JSON (on prend la dernière ligne qui commence par "{" au cas où il y aurait d'autres messages)
const ligneJson = sortie.stdout.trim().split(/\r?\n/).reverse().find(l => l.trim().startsWith('{'));
if (!ligneJson) {
  throw new Error('Aucun JSON trouvé dans stdout : ' + sortie.stdout);
}

const res = JSON.parse(ligneJson);
if (!res.success) {
  throw new Error('Extraction échouée : ' + res.error);
}

// "432 627" -> 432627 ; "0,90383" -> 0.90383
const num = (s) => s == null ? null : parseFloat(String(s).replace(/\s/g, '').replace(',', '.'));

// Un item n8n par ligne de facture
return res.lignes.map((l) => ({
  json: {
    designation: l.designation,
    quantite: l.quantite,              // texte d'origine
    prix_unitaire: l.prix_unitaire,    // texte d'origine
    quantite_num: num(l.quantite),     // nombre
    prix_unitaire_num: num(l.prix_unitaire),
    fichier: res.chemin,
  },
}));
